export default function install(app){const style=document.createElement('style');style.id='prowise-drawing-tools-type';style.textContent=`#prowise-tools-panel{font-family:Poppins,sans-serif;font-size:18px;font-weight:500;line-height:1.45}#prowise-tools-panel .pw-header{font-family:Poppins,sans-serif;font-size:22px;font-weight:500;line-height:1.45}#prowise-tools-panel .pw-body,#prowise-tools-panel .pw-color-row label,#prowise-tools-panel .pw-reading{font-family:Poppins,sans-serif;font-size:18px;font-weight:500;line-height:1.45}#prowise-tools-panel .pw-tools button,#prowise-tools-panel .pw-body>button{font-family:Poppins,sans-serif;font-size:18px;font-weight:500;line-height:1.35}#prowise-tools-panel .pw-hint{font-family:Poppins,sans-serif;font-size:16px;font-weight:500;line-height:1.5}#prowise-tools-panel .pw-header button{font-family:Poppins,sans-serif;font-size:23px;font-weight:500}#prowise-tools-panel input[type=color]{font-family:Poppins,sans-serif}`;document.head.append(style);app.onCleanup(()=>style.remove());return {panelFont:'Poppins',bodySize:'18px',headerSize:'22px',hintSize:'16px'}}